function esc($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function gateway(array $input):array{
    global $config,$uid;
    $input['uid']=$uid;$body=json_encode($input,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$ts=(string)time();$nonce=bin2hex(random_bytes(16));
    $sig=hash_hmac('sha256',$ts."\n".$nonce."\n".$body,$config['gateway_key']);
    $ch=curl_init($config['gateway_url']);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Arcenal-Timestamp: '.$ts,'X-Arcenal-Nonce: '.$nonce,'X-Arcenal-Signature: '.$sig]]);
    $response=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
    if($response===false||$code!==200)throw new RuntimeException('Transmission non confirmée. Conservez votre saisie et réessayez ; si elle a déjà été reçue, elle ne sera pas dupliquée.');
    $data=json_decode($response,true,16,JSON_THROW_ON_ERROR);if(!is_array($data))throw new RuntimeException('Réponse indisponible.');return $data;
}
