if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf'])){http_response_code(403);exit('Formulaire expiré.');}
    try{
        if(($_POST['form']??'report')==='action'){
            $res=gateway(['operation'=>'action.progress','request_id'=>(string)($_POST['request_id']??''),'action_id'=>(int)($_POST['action_id']??0),'version'=>(int)($_POST['version']??0),'progress'=>(int)($_POST['progress']??-1),'note'=>(string)($_POST['note']??'')]);$success='Avancement enregistré pour '.$res['reference'].'.';
        }elseif(($_POST['form']??'report')==='mat'){
            $input=[];foreach(['mat_feeling','mat_equipment','mat_documents','mat_conditions','mat_risks','observation'] as $field)$input[$field]=is_string($_POST[$field]??null)?$_POST[$field]:'';$res=gateway(['operation'=>'mat.submit','request_id'=>(string)($_SESSION['mat_request_id']??''),'record'=>$input]);$success=$res['alert']?'MAT enregistrée. Prends immédiatement contact avec ton responsable et ne débute pas le travail dans ces conditions.':'MAT enregistrée. Bonne journée, bon travail et prends soin de toi.';unset($_SESSION['mat_request_id']);
        }else{
            $input=[];foreach(['title','description','context_label','location','occurred_at','origin','immediate_action','category','severity','report_type','nc_type','analysis_immediate'] as $field)$input[$field]=is_string($_POST[$field]??null)?$_POST[$field]:'';
            if(!empty($_FILES['photo']['tmp_name'])){if((int)$_FILES['photo']['error']!==UPLOAD_ERR_OK||(int)$_FILES['photo']['size']>2097152)throw new RuntimeException('Photo invalide ou supérieure à 2 Mo.');$input['photo']=['name'=>(string)$_FILES['photo']['name'],'content'=>base64_encode((string)file_get_contents($_FILES['photo']['tmp_name']))];}
            $res=gateway(['operation'=>'submit','request_id'=>(string)($_SESSION['request_id']??''),'record'=>$input]);$success='Remontée reçue : '.$res['reference'];$sent=true;unset($_SESSION['request_id']);
        }
    }catch(Throwable $e){$error=$e->getMessage();}
}
try{$data=gateway(['operation'=>'list']);}catch(Throwable $e){$error=$error?:'Vos remontées sont temporairement indisponibles ou votre accès a été retiré.';}
